spl_autoload_register(function($class)use($root){if(str_starts_with($class,'App\\Domain\\Akubica\\Benefits\\'))require $root.'/app/'.str_replace('\\','/',substr($class,4)).'.php';});
require __DIR__.'/FixtureBenefitStore.php';
use App\Domain\Akubica\Benefits\{BenefitActor,BenefitsAuthorizer,DisabledBenefitsAuthorizer,BenefitFailure,OpaqueBenefitWorkflow,OpaqueReference,PartialCredit};
final class SyntheticApprovalOnly implements BenefitsAuthorizer {public bool $allowed=true;public function authorize(BenefitActor $actor,string $operation,int $now):void{if(!$this->allowed)throw new BenefitFailure('CONSUMER_NOT_AUTHORIZED');}}
$rows=[];
function eq($a,$b):void{if($a!==$b)throw new RuntimeException('Synthetic invariant failed');}
function rejects(string $code,callable $f):void{try{$f();}catch(BenefitFailure $e){eq($code,$e->errorCode);return;}throw new RuntimeException('Expected rejection');}
function testCase(string $name,callable $test):void{global $rows;try{$test();$rows[]=['case_id'=>$name,'result'=>'PASS'];}catch(Throwable $e){$rows[]=['case_id'=>$name,'result'=>'FAIL','category'=>get_class($e)];}}
function setupFixture(string $kind='credit',int $remaining=1500,int $subtotal=1000,string $file=':memory:'):array{
 $s=new FixtureBenefitStore($file);$actor=new BenefitActor(11,'synthetic-consumer','synthetic-delegation');$cart=OpaqueReference::issue('crt');$auth=new SyntheticApprovalOnly;
 $s->put('carts',OpaqueReference::key($cart,'crt'),['user_id'=>11,'consumer_id'=>$actor->consumerId,'delegation_id'=>$actor->delegationId,'service_line'=>'medical_services','active'=>true,'subtotal_cents'=>$subtotal,'revision'=>1,'version'=>OpaqueReference::issue('ver'),'application'=>null]);
 $s->put('sources','source-synthetic',['user_id'=>11,'kind'=>$kind,'active'=>true,'approved'=>true,'service_line'=>'medical_services','remaining_cents'=>$remaining,'minimum_cents'=>0,'starts_at'=>900,'expires_at'=>2000]);
 return [$s,new OpaqueBenefitWorkflow($s,$auth),$actor,$cart,$auth];
}
/** Synthetic receipt fixture, NOT a production consent endpoint/issuer. */
function intent(FixtureBenefitStore $s,BenefitActor $a,array $snapshot,string $op='apply',?string $application=null):array{
 $target=$op==='apply'?$snapshot['benefits'][0]['benefit_ref']:$application;$ref=OpaqueReference::issue('cnf');
 $kind=$snapshot['benefits'][0]['benefit_type']??null;$amount=$op==='apply'?$snapshot['benefits'][0]['max_applicable_cents']:0;
 $totals=['subtotal_cents'=>$snapshot['totals']['subtotal_cents'],'discount_cents'=>$op==='apply'&&$kind==='coupon'?$amount:0,'credit_applied_cents'=>$op==='apply'&&$kind==='credit'?$amount:0,'total_cents'=>$snapshot['totals']['subtotal_cents']-$amount,'currency'=>'MXN'];
 $s->put('confirmations',OpaqueReference::key($ref,'cnf'),['actor'=>$a->namespace(),'cart_ref'=>$snapshot['cart_ref'],'cart_version'=>$snapshot['cart_version'],'operation'=>$op,'target'=>$target,'amount'=>$amount,'totals'=>$totals,'text_version'=>'synthetic-proposal-v1','expires_at'=>1120,'used'=>false]);
 return ['service_line'=>'medical_services','cart_ref'=>$snapshot['cart_ref'],'cart_version'=>$snapshot['cart_version'],'confirmation_ref'=>$ref,$op==='apply'?'benefit_ref':'application_ref'=>$target];
}
$key='synthetic-intention-0001';
