testCase('OPAQUE_RANDOM_CANONICAL_REFERENCES',function(){ $seen=[];for($i=0;$i<100;$i++){ $r=OpaqueReference::issue('bnf');eq(true,OpaqueReference::valid($r,'bnf'));eq(false,isset($seen[$r]));$seen[$r]=true;eq(false,OpaqueReference::valid($r."\n",'bnf'));eq(false,OpaqueReference::valid($r,'app'));} });
testCase('CATALOG_ELIGIBILITY_AND_NO_PRIVATE_FIELDS',function(){[$s,$w,$a,$c]=setupFixture();$src=$s->get('sources','source-synthetic');foreach(['foreign'=>['user_id'=>99],'expired'=>['expires_at'=>999],'future'=>['starts_at'=>1001],'disabled'=>['active'=>false],'unapproved'=>['approved'=>false],'empty'=>['remaining_cents'=>0],'minimum'=>['minimum_cents'=>1001],'otherline'=>['service_line'=>'laboratory']] as $id=>$change)$s->put('sources',$id,array_replace($src,$change));$v=$w->preview($a,$c,1000);eq(1,count($v['benefits']));eq(['benefit_ref','benefit_type','estimated_amount_cents','max_applicable_cents','reference_expires_at'],array_keys($v['benefits'][0]));eq(1500,$s->get('sources','source-synthetic')['remaining_cents']);eq(null,$s->get('carts',OpaqueReference::key($c,'crt'))['application']);});
foreach(['coupon','credit'] as $kind){testCase(strtoupper($kind).'_APPLY_REMOVE_NO_CONSUMPTION',function()use($kind,$key){[$s,$w,$a,$c]=setupFixture($kind);$v=$w->preview($a,$c,1000);$b=intent($s,$a,$v);$result=$w->apply($a,$b,$key,1000);eq('applied',$result['status']);eq(0,$result['totals']['total_cents']);eq(1000,$result['totals'][$kind==='credit'?'credit_applied_cents':'discount_cents']);eq(1500,$s->get('sources','source-synthetic')['remaining_cents']);$v=$w->preview($a,$c,1001);$remove=intent($s,$a,$v,'remove',$result['application_ref']);$removed=$w->remove($a,$remove,'synthetic-remove-0001',1001);eq('removed',$removed['status']);eq(1000,$removed['totals']['total_cents']);eq(1500,$s->get('sources','source-synthetic')['remaining_cents']);eq(null,$w->preview($a,$c,1002)['application']);});}
