testCase('PARTIAL_DEBIT_ARITHMETIC_PRESERVES_REMAINDER',function(){eq(500,PartialCredit::remainingAfterConfirmedDebit(1500,1000));rejects('INSUFFICIENT_CREDIT',fn()=>PartialCredit::remainingAfterConfirmedDebit(500,501));rejects('INSUFFICIENT_CREDIT',fn()=>PartialCredit::remainingAfterConfirmedDebit(500,0));});
