testCase('AUTHORIZATION_BEFORE_REPLAY',function()use($key){[$s,$w,$a,$c,$auth]=setupFixture();$b=intent($s,$a,$w->preview($a,$c,1000));$w->apply($a,$b,$key,1000);$auth->allowed=false;rejects('CONSUMER_NOT_AUTHORIZED',fn()=>$w->apply($a,$b,$key,1001));});
testCase('IDEMPOTENCY_CONFLICT',function()use($key){[$s,$w,$a,$c]=setupFixture();$b=intent($s,$a,$w->preview($a,$c,1000));$w->apply($a,$b,$key,1000);$b['confirmation_ref']=OpaqueReference::issue('cnf');rejects('IDEMPOTENCY_KEY_CONFLICT',fn()=>$w->apply($a,$b,$key,1001));});
foreach(['coupon_id','credit_id','consent','requested_amount_cents'] as $field)testCase('REJECT_EXTRA_FIELD_'.$field,function()use($key,$field){[$s,$w,$a,$c]=setupFixture();$b=intent($s,$a,$w->preview($a,$c,1000));$b[$field]='synthetic';rejects('VALIDATION_ERROR',fn()=>$w->apply($a,$b,$key,1000));});
foreach(['operation'=>'remove','amount'=>999,'cart_version'=>'OTHER','actor'=>'OTHER','expires_at'=>1000,'used'=>true,'text_version'=>''] as $field=>$value)testCase('CONSENT_REJECT_'.$field,function()use($key,$field,$value){[$s,$w,$a,$c]=setupFixture();$b=intent($s,$a,$w->preview($a,$c,1000));$k=OpaqueReference::key($b['confirmation_ref'],'cnf');$consent=$s->get('confirmations',$k);$consent[$field]=$value;$s->put('confirmations',$k,$consent);$code=match($field){'actor'=>'CONFIRMATION_REFERENCE_NOT_FOUND','expires_at'=>'CONFIRMATION_EXPIRED','used'=>'CONFIRMATION_ALREADY_USED',default=>'CONFIRMATION_CONTEXT_CHANGED'};rejects($code,fn()=>$w->apply($a,$b,$key,1000));eq([],$s->all('applications'));});
testCase('OPTION_EXPIRY_AT_BOUNDARY',function()use($key){[$s,$w,$a,$c]=setupFixture();$b=intent($s,$a,$w->preview($a,$c,1000));$k=OpaqueReference::key($b['benefit_ref'],'bnf');$o=$s->get('options',$k);$o['expires_at']=1000;$s->put('options',$k,$o);rejects('BENEFIT_REFERENCE_EXPIRED',fn()=>$w->apply($a,$b,$key,1000));});
