testCase('ATOMIC_ROLLBACK_WHEN_RECEIPT_WRITE_FAILS',function()use($key){[$s,$w,$a,$c]=setupFixture();$b=intent($s,$a,$w->preview($a,$c,1000));$s->failReceipt=true;try{$w->apply($a,$b,$key,1000);throw new LogicException('Expected storage failure');}catch(RuntimeException $e){if($e instanceof LogicException)throw $e;}eq([],$s->all('applications'));eq(null,$s->get('carts',OpaqueReference::key($c,'crt'))['application']);eq(false,$s->get('confirmations',OpaqueReference::key($b['confirmation_ref'],'cnf'))['used']);$s->failReceipt=false;eq('applied',$w->apply($a,$b,$key,1000)['status']);});
testCase('TWO_REAL_PROCESSES_SERIALIZE_ONE_CART',function()use($key){
 if(!function_exists('pcntl_fork'))throw new RuntimeException('PCNTL unavailable');
 $dir=sys_get_temp_dir().'/famedic-benefits-fixture-'.bin2hex(random_bytes(8));mkdir($dir,0700);$db=$dir.'/state.sqlite';
 try{[$s,$w,$a,$c]=setupFixture('credit',1500,1000,$db);$v=$w->preview($a,$c,1000);$b1=intent($s,$a,$v);$b2=intent($s,$a,$v);$children=[];
 foreach([$b1,$b2] as $i=>$body){$pid=pcntl_fork();if($pid<0)throw new RuntimeException('Fork unavailable');if($pid===0){$store=new FixtureBenefitStore($db);$worker=new OpaqueBenefitWorkflow($store,new SyntheticApprovalOnly);try{$worker->apply($a,$body,$key.'-'.$i,1000);$result='APPLIED';}catch(BenefitFailure $e){$result=$e->errorCode;}file_put_contents($dir.'/worker-'.$i,$result);exit(0);} $children[]=$pid;}
 foreach($children as $pid){pcntl_waitpid($pid,$status);eq(0,pcntl_wexitstatus($status));}
 $results=[file_get_contents($dir.'/worker-0'),file_get_contents($dir.'/worker-1')];sort($results);eq(['APPLIED','CART_VERSION_CONFLICT'],$results);eq(1,count($s->all('applications')));eq(1500,$s->get('sources','source-synthetic')['remaining_cents']);
 }finally{foreach(glob($dir.'/*') as $f)unlink($f);rmdir($dir);}
});

final class SyntheticPurchaseOnly implements \App\Domain\Akubica\Benefits\MedicalPurchaseVerifier{
 public function __construct(public ?\App\Domain\Akubica\Benefits\VerifiedMedicalDebit $proof){}
 public function verifiedDebit(BenefitActor $actor,string $purchaseReference):?\App\Domain\Akubica\Benefits\VerifiedMedicalDebit{return $this->proof;}
}
function finalizer(FixtureBenefitStore $s,?\App\Domain\Akubica\Benefits\VerifiedMedicalDebit $proof):\App\Domain\Akubica\Benefits\PartialCreditFinalizer{return new \App\Domain\Akubica\Benefits\PartialCreditFinalizer($s,new SyntheticApprovalOnly,new SyntheticPurchaseOnly($proof));}
function debitProof(string $purchase='synthetic-purchase',int $amount=700,int $user=11):\App\Domain\Akubica\Benefits\VerifiedMedicalDebit{return new \App\Domain\Akubica\Benefits\VerifiedMedicalDebit($purchase,$user,'source-synthetic',$amount);}
testCase('FINALIZER_EXACT_PARTIAL_DEBIT_AND_PERMANENT_REPLAY',function(){[$s,$w,$a,$c]=setupFixture('credit',1500);$f=finalizer($s,debitProof());$result=$f->finalize($a,'synthetic-purchase',1000);eq(700,$result['debited_cents']);eq(800,$result['remaining_cents']);eq(true,$f->finalize($a,'synthetic-purchase',1001)['replayed']);eq(800,$s->get('sources','source-synthetic')['remaining_cents']);eq(1,count($s->all('debits')));});
testCase('FINALIZER_REQUIRES_VERIFIED_FIRST_PARTY_PURCHASE',function(){[$s,$w,$a,$c]=setupFixture();rejects('PURCHASE_NOT_VERIFIED',fn()=>finalizer($s,null)->finalize($a,'synthetic-purchase',1000));rejects('PURCHASE_NOT_VERIFIED',fn()=>finalizer($s,debitProof(user:99))->finalize($a,'synthetic-purchase',1000));eq(1500,$s->get('sources','source-synthetic')['remaining_cents']);});
testCase('FINALIZER_REJECTS_CHANGED_PURCHASE_RECEIPT',function(){[$s,$w,$a,$c]=setupFixture();finalizer($s,debitProof())->finalize($a,'synthetic-purchase',1000);rejects('PURCHASE_DEBIT_CONFLICT',fn()=>finalizer($s,debitProof(amount:701))->finalize($a,'synthetic-purchase',1001));});
testCase('FINALIZER_DEFAULT_DISABLED',function(){[$s,$w,$a,$c]=setupFixture();$f=new \App\Domain\Akubica\Benefits\PartialCreditFinalizer($s,new DisabledBenefitsAuthorizer,new SyntheticPurchaseOnly(debitProof()));rejects('BENEFITS_PENDING_APPROVAL',fn()=>$f->finalize($a,'synthetic-purchase',1000));eq([],$s->all('debits'));});
testCase('TWO_PURCHASE_PROCESSES_CANNOT_OVERDRAW_CREDIT',function(){
 $dir=sys_get_temp_dir().'/famedic-benefits-fixture-'.bin2hex(random_bytes(8));mkdir($dir,0700);$db=$dir.'/state.sqlite';
 try{[$s,$w,$a,$c]=setupFixture('credit',1000,1000,$db);$children=[];
 foreach([0,1] as $i){$pid=pcntl_fork();if($pid<0)throw new RuntimeException('Fork unavailable');if($pid===0){$store=new FixtureBenefitStore($db);$ref='synthetic-purchase-'.$i;try{finalizer($store,debitProof($ref))->finalize($a,$ref,1000);$result='DEBITED';}catch(BenefitFailure $e){$result=$e->errorCode;}file_put_contents($dir.'/worker-'.$i,$result);exit(0);} $children[]=$pid;}
 foreach($children as $pid){pcntl_waitpid($pid,$status);eq(0,pcntl_wexitstatus($status));}
 $results=[file_get_contents($dir.'/worker-0'),file_get_contents($dir.'/worker-1')];sort($results);eq(['DEBITED','INSUFFICIENT_CREDIT'],$results);eq(300,$s->get('sources','source-synthetic')['remaining_cents']);eq(1,count($s->all('debits')));
 }finally{foreach(glob($dir.'/*') as $f)unlink($f);rmdir($dir);}
});

